CREATE OR REPLACE FUNCTION public.mark_fulfillment_status(p_user_id uuid, p_record_date date, p_status text, p_reason text DEFAULT NULL::text, p_marker_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  marker_id uuid;
  member_team_id uuid;
  result_id uuid;
BEGIN
  IF NOT public.is_admin_or_owner() THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  IF p_status NOT IN ('leave', 'waived', 'absent', 'confirmed_published') THEN
    RAISE EXCEPTION 'invalid status: %', p_status;
  END IF;

  marker_id := COALESCE(
    p_marker_id,
    CASE WHEN auth.role() = 'service_role' THEN NULL ELSE auth.uid() END
  );

  SELECT team_id INTO member_team_id
  FROM public.profiles
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'member not found';
  END IF;

  INSERT INTO public.fulfillment_records (user_id, record_date, status, reason, marked_by, team_id, group_id)
  VALUES (p_user_id, p_record_date, p_status, p_reason, marker_id, member_team_id, NULL)
  ON CONFLICT (user_id, record_date)
  DO UPDATE SET
    status = EXCLUDED.status,
    reason = EXCLUDED.reason,
    marked_by = EXCLUDED.marked_by,
    team_id = EXCLUDED.team_id,
    group_id = NULL,
    marked_at = now()
  RETURNING id INTO result_id;

  IF marker_id IS NOT NULL THEN
    INSERT INTO public.audit_logs (user_id, action, target, detail)
    VALUES (
      marker_id,
      'mark_fulfillment',
      p_user_id::text,
      jsonb_build_object(
        'record_date', p_record_date,
        'status', p_status,
        'reason', COALESCE(p_reason, '')
      )::text
    );
  END IF;

  RETURN jsonb_build_object('id', result_id, 'status', p_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_fulfillment_status_batch(p_user_ids uuid[], p_record_date date, p_status text, p_reason text DEFAULT NULL::text, p_marker_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  marker_id uuid;
  affected_count int;
BEGIN
  IF NOT public.is_admin_or_owner() THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'user ids are required';
  END IF;

  IF array_length(p_user_ids, 1) > 200 THEN
    RAISE EXCEPTION 'too many users';
  END IF;

  IF p_status NOT IN ('leave', 'waived', 'absent', 'confirmed_published') THEN
    RAISE EXCEPTION 'invalid status: %', p_status;
  END IF;

  marker_id := COALESCE(
    p_marker_id,
    CASE WHEN auth.role() = 'service_role' THEN NULL ELSE auth.uid() END
  );

  WITH target_members AS (
    SELECT DISTINCT p.id, p.team_id
    FROM public.profiles p
    WHERE p.id = ANY(p_user_ids)
  ),
  upserted AS (
    INSERT INTO public.fulfillment_records (user_id, record_date, status, reason, marked_by, team_id, group_id)
    SELECT id, p_record_date, p_status, p_reason, marker_id, team_id, NULL
    FROM target_members
    ON CONFLICT (user_id, record_date)
    DO UPDATE SET
      status = EXCLUDED.status,
      reason = EXCLUDED.reason,
      marked_by = EXCLUDED.marked_by,
      team_id = EXCLUDED.team_id,
      group_id = NULL,
      marked_at = now()
    RETURNING user_id
  )
  SELECT count(*)::int INTO affected_count
  FROM upserted;

  IF marker_id IS NOT NULL THEN
    INSERT INTO public.audit_logs (user_id, action, target, detail)
    VALUES (
      marker_id,
      'mark_fulfillment_batch',
      'fulfillment_records',
      jsonb_build_object(
        'record_date', p_record_date,
        'status', p_status,
        'reason', COALESCE(p_reason, ''),
        'requested_count', array_length(p_user_ids, 1),
        'affected_count', affected_count
      )::text
    );
  END IF;

  RETURN jsonb_build_object('affected_count', affected_count, 'status', p_status);
END;
$function$
